insert into public.translations (locale, key, value) values
  ('pt-BR', 'mods.description', $json$"Mods acrescentam coisas ao JayV, como os mods de um jogo: motores de LLM, recursos, agentes e o que mais o app aprender a receber. Instale, ligue, desligue e desinstale cada um aqui; as mudanças valem quando você salva. Os mods que vieram com a sua conta estão instalados e ligados."$json$::jsonb),
  ('en', 'mods.description', $json$"Mods add to JayV, like mods in a game: LLM engines, features, agents and whatever the app learns to take next. Install, turn on, turn off and uninstall each one here; the changes apply when you save. The mods that came with your account are installed and on."$json$::jsonb),
  ('es', 'mods.description', $json$"Los mods añaden cosas a JayV, como los mods de un juego: motores de LLM, funciones, agentes y lo que la app aprenda a recibir después. Instala, activa, desactiva y desinstala cada uno aquí; los cambios valen al guardar. Los mods que vinieron con tu cuenta están instalados y activados."$json$::jsonb),
  ('zh-CN', 'mods.description', $json$"模组为 JayV 增添内容，就像游戏里的模组：LLM 引擎、功能、智能体，以及应用今后能接收的其他内容。在这里安装、开启、关闭和卸载每个模组；保存后生效。随账户提供的模组已安装并开启。"$json$::jsonb),
  ('hi', 'mods.description', $json$"मॉड JayV में चीज़ें जोड़ते हैं, जैसे किसी गेम के मॉड: LLM इंजन, सुविधाएँ, एजेंट और ऐप आगे जो भी लेना सीखे। हर एक को यहाँ इंस्टॉल, चालू, बंद और अनइंस्टॉल करें; बदलाव सहेजने पर लागू होते हैं। आपके खाते के साथ आए मॉड इंस्टॉल और चालू हैं।"$json$::jsonb),
  ('ar', 'mods.description', $json$"تضيف الإضافات إلى JayV كما تفعل إضافات الألعاب: محركات LLM وميزات ووكلاء وكل ما يتعلم التطبيق استقباله لاحقًا. ثبّت كل إضافة وفعّلها وعطّلها وألغِ تثبيتها هنا؛ تسري التغييرات عند الحفظ. الإضافات التي جاءت مع حسابك مثبّتة ومفعّلة."$json$::jsonb),
  ('fr', 'mods.description', $json$"Les mods ajoutent des choses à JayV, comme les mods d’un jeu : moteurs LLM, fonctionnalités, agents et tout ce que l’app saura recevoir ensuite. Installez, activez, désactivez et désinstallez chacun ici ; les changements s’appliquent à l’enregistrement. Les mods fournis avec votre compte sont installés et activés."$json$::jsonb),
  ('ru', 'mods.description', $json$"Моды добавляют возможности в JayV, как моды в играх: движки LLM, функции, агентов и всё, что приложение научится принимать дальше. Устанавливайте, включайте, выключайте и удаляйте каждый здесь; изменения вступают в силу после сохранения. Моды, пришедшие с вашей учётной записью, установлены и включены."$json$::jsonb),
  ('ja', 'mods.description', $json$"Mod はゲームの Mod のように JayV に機能を追加します。LLM エンジン、機能、エージェント、そして今後アプリが受け取れるようになるもの。ここで各 Mod をインストール、オン、オフ、アンインストールできます。変更は保存したときに反映されます。アカウントに付属する Mod はインストール済みでオンです。"$json$::jsonb),
  ('de', 'mods.description', $json$"Mods erweitern JayV wie Mods in einem Spiel: LLM-Engines, Funktionen, Agenten und alles, was die App künftig aufnehmen kann. Installieren, einschalten, ausschalten und deinstallieren Sie jeden hier; Änderungen gelten beim Speichern. Die Mods, die mit Ihrem Konto kamen, sind installiert und eingeschaltet."$json$::jsonb),
  ('pt-BR', 'mods.catalog.none', $json$"O catálogo de mods ainda não foi baixado: tudo o que vem no app continua ligado até ele chegar."$json$::jsonb),
  ('en', 'mods.catalog.none', $json$"The catalog of mods hasn't been downloaded yet: everything built into the app stays on until it is."$json$::jsonb),
  ('es', 'mods.catalog.none', $json$"El catálogo de mods aún no se ha descargado: todo lo que trae la app sigue activado hasta que llegue."$json$::jsonb),
  ('zh-CN', 'mods.catalog.none', $json$"模组目录尚未下载：在下载之前，应用自带的一切保持开启。"$json$::jsonb),
  ('hi', 'mods.catalog.none', $json$"मॉड का कैटलॉग अभी डाउनलोड नहीं हुआ है: उसके आने तक ऐप में शामिल सब कुछ चालू रहता है।"$json$::jsonb),
  ('ar', 'mods.catalog.none', $json$"لم يُنزَّل فهرس الإضافات بعد: يبقى كل ما في التطبيق مفعّلًا حتى يصل."$json$::jsonb),
  ('fr', 'mods.catalog.none', $json$"Le catalogue des mods n’a pas encore été téléchargé : tout ce qui est intégré à l’app reste activé jusqu’à son arrivée."$json$::jsonb),
  ('ru', 'mods.catalog.none', $json$"Каталог модов ещё не загружен: всё встроенное в приложение остаётся включённым, пока он не придёт."$json$::jsonb),
  ('ja', 'mods.catalog.none', $json$"Mod のカタログはまだダウンロードされていません。届くまではアプリに組み込まれたものはすべてオンのままです。"$json$::jsonb),
  ('de', 'mods.catalog.none', $json$"Der Mod-Katalog wurde noch nicht heruntergeladen: Alles, was in die App eingebaut ist, bleibt bis dahin eingeschaltet."$json$::jsonb),
  ('pt-BR', 'mods.notes.site', $json$"Todo mod vem do repositório de mods do JayV, e o que você instala acompanha este ambiente nos seus outros computadores e no site. Os seus próprios mods são criados no site; as chaves de API ficam neste computador. O plano continua decidindo, e nos projetos de uma organização a política de LLM dela vale para todo mod."$json$::jsonb),
  ('en', 'mods.notes.site', $json$"Every mod comes from the JayV mods repository, and what you install follows this environment to your other computers and to the site. Your own mods are created on the site; API keys stay on this computer. Your plan still decides, and in an organization's projects its LLM policy applies to every mod."$json$::jsonb),
  ('es', 'mods.notes.site', $json$"Cada mod viene del repositorio de mods de JayV, y lo que instalas acompaña a este entorno en tus otros equipos y en el sitio. Tus propios mods se crean en el sitio; las claves de API se quedan en este equipo. Tu plan sigue decidiendo, y en los proyectos de una organización su política de LLM se aplica a todos los mods."$json$::jsonb),
  ('zh-CN', 'mods.notes.site', $json$"每个模组都来自 JayV 的模组仓库，你安装的内容会随此环境同步到你的其他电脑和网站。你自己的模组在网站上创建；API 密钥只保存在这台电脑上。套餐仍然决定可用内容，在组织的项目中，组织的 LLM 策略适用于所有模组。"$json$::jsonb),
  ('hi', 'mods.notes.site', $json$"हर मॉड JayV के मॉड रिपॉज़िटरी से आता है, और आप जो इंस्टॉल करते हैं वह इस वातावरण के साथ आपके दूसरे कंप्यूटरों और साइट तक जाता है। आपके अपने मॉड साइट पर बनते हैं; API कुंजियाँ इसी कंप्यूटर पर रहती हैं। आपका प्लान अब भी तय करता है, और किसी संगठन के प्रोजेक्ट में उसकी LLM नीति हर मॉड पर लागू होती है।"$json$::jsonb),
  ('ar', 'mods.notes.site', $json$"تأتي كل إضافة من مستودع إضافات JayV، وما تثبّته يرافق هذه البيئة إلى أجهزتك الأخرى وإلى الموقع. تُنشأ إضافاتك الخاصة على الموقع؛ وتبقى مفاتيح API على هذا الجهاز. تظل خطتك هي الحاكمة، وفي مشاريع المؤسسة تسري سياسة LLM الخاصة بها على كل إضافة."$json$::jsonb),
  ('fr', 'mods.notes.site', $json$"Chaque mod vient du dépôt de mods de JayV, et ce que vous installez suit cet environnement sur vos autres ordinateurs et sur le site. Vos propres mods se créent sur le site ; les clés d’API restent sur cet ordinateur. Votre forfait décide toujours, et dans les projets d’une organisation sa politique LLM s’applique à chaque mod."$json$::jsonb),
  ('ru', 'mods.notes.site', $json$"Каждый мод берётся из репозитория модов JayV, а то, что вы устанавливаете, следует за этим окружением на другие ваши компьютеры и на сайт. Свои моды создаются на сайте; ключи API остаются на этом компьютере. Тариф по-прежнему решает, а в проектах организации её политика LLM действует для всех модов."$json$::jsonb),
  ('ja', 'mods.notes.site', $json$"すべての Mod は JayV の Mod リポジトリから届き、インストールしたものはこの環境とともに他のコンピューターやサイトにも反映されます。自分の Mod はサイトで作成します。API キーはこのコンピューターにだけ保存されます。プランは引き続き適用され、組織のプロジェクトではその LLM ポリシーがすべての Mod に適用されます。"$json$::jsonb),
  ('de', 'mods.notes.site', $json$"Jeder Mod stammt aus dem Mod-Repository von JayV, und was Sie installieren, folgt dieser Umgebung auf Ihre anderen Computer und auf die Website. Eigene Mods erstellen Sie auf der Website; API-Schlüssel bleiben auf diesem Computer. Ihr Tarif entscheidet weiterhin, und in den Projekten einer Organisation gilt deren LLM-Richtlinie für jeden Mod."$json$::jsonb),
