  ('hi', 'mods.installedEmpty', $json$"कोई मॉड इंस्टॉल नहीं है। नीचे दिए कैटलॉग से एक इंस्टॉल करें।"$json$::jsonb),
  ('ar', 'mods.installedEmpty', $json$"لا توجد إضافة مثبّتة. ثبّت واحدة من الفهرس أدناه."$json$::jsonb),
  ('fr', 'mods.installedEmpty', $json$"Aucun mod installé. Installez-en un depuis le catalogue ci-dessous."$json$::jsonb),
  ('ru', 'mods.installedEmpty', $json$"Ни один мод не установлен. Установите мод из каталога ниже."$json$::jsonb),
  ('ja', 'mods.installedEmpty', $json$"インストール済みの Mod はありません。下のカタログからインストールしてください。"$json$::jsonb),
  ('de', 'mods.installedEmpty', $json$"Kein Mod installiert. Installieren Sie einen aus dem Katalog unten."$json$::jsonb),
